function createRequest(x={}) { const ids=arr(x.equipmentIds||x.items).map(v=>Number(v.id||v));if(!x.requesterId||!ids.length)throw Error('requesterId and equipmentIds are required');const tx=db.transaction(()=>{const u=db.prepare('SELECT * FROM users WHERE id=?').get(x.requesterId);if(!u)throw Error('user not found');if(u.banned)throw Error('user is banned');const conflicts=checkAvailability(ids,x.pickupStartsAt,x.returnEndsAt);if(conflicts.length)throw Error('equipment unavailable: '+conflicts.join(','));const r=db.prepare('INSERT INTO requests(requester_id,purpose,academic_priority) VALUES (?,?,?)').run(x.requesterId,x.purpose||'',x.academicPriority||0);for(const eid of ids){db.prepare('INSERT INTO request_items(request_id,equipment_id) VALUES (?,?)').run(r.lastInsertRowid,eid);db.prepare('UPDATE equipment SET status="requested",updated_at=? WHERE id=?').run(now(),eid);}if(x.pickupStartsAt&&x.pickupEndsAt)db.prepare('INSERT INTO time_windows(request_id,kind,starts_at,ends_at) VALUES (?,?,?,?,?)').run(r.lastInsertRowid,'pickup',x.pickupStartsAt,x.pickupEndsAt);if(x.returnStartsAt&&x.returnEndsAt)db.prepare('INSERT INTO time_windows(request_id,kind,starts_at,ends_at) VALUES (?,?,?,?,?)').run(r.lastInsertRowid,'return',x.returnStartsAt,x.returnEndsAt);audit(x.requesterId,'request',r.lastInsertRowid,'created',{equipmentIds:ids});emit('request.created','request',r.lastInsertRowid,{equipmentIds:ids});return r.lastInsertRowid;});return requestView(tx()); }
