'use strict';

const path = require('node:path');
const Database = require('better-sqlite3');

const dbPath = process.env.MEDIA_LAB_DB || path.join(__dirname, 'media-lab.sqlite');
const db = new Database(dbPath);
db.pragma('journal_mode = WAL');
db.pragma('foreign_keys = ON');

db.exec(
  'CREATE TABLE IF NOT EXISTS equipment (' +
  'id INTEGER PRIMARY KEY, asset_code TEXT NOT NULL UNIQUE, name TEXT NOT NULL,' +
  'description TEXT NOT NULL DEFAULT "", serial_number TEXT UNIQUE,' +
  'status TEXT NOT NULL DEFAULT "available" CHECK(status IN ("available","checked_out","maintenance","retired","lost")),' +
  'location TEXT NOT NULL DEFAULT "", created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,' +
  'updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);' +
  'CREATE TABLE IF NOT EXISTS lendees (' +
  'id INTEGER PRIMARY KEY, name TEXT NOT NULL, email TEXT NOT NULL UNIQUE,' +
  'phone TEXT NOT NULL DEFAULT "", notes TEXT NOT NULL DEFAULT "", created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);' +
  'CREATE TABLE IF NOT EXISTS tags (id INTEGER PRIMARY KEY, name TEXT NOT NULL UNIQUE);' +
  'CREATE TABLE IF NOT EXISTS equipment_tags (' +
  'equipment_id INTEGER NOT NULL REFERENCES equipment(id) ON DELETE CASCADE,' +
  'tag_id INTEGER NOT NULL REFERENCES tags(id) ON DELETE CASCADE,' +
  'PRIMARY KEY(equipment_id, tag_id));' +
  'CREATE TABLE IF NOT EXISTS loans (' +
  'id INTEGER PRIMARY KEY, equipment_id INTEGER NOT NULL REFERENCES equipment(id),' +
  'lendee_id INTEGER NOT NULL REFERENCES lendees(id), picked_up_at TEXT NOT NULL,' +
  'due_at TEXT, returned_at TEXT, pickup_notes TEXT NOT NULL DEFAULT "",' +
  'return_notes TEXT NOT NULL DEFAULT "", condition_out TEXT NOT NULL DEFAULT "",' +
  'condition_in TEXT NOT NULL DEFAULT "");' +
  'CREATE INDEX IF NOT EXISTS idx_equipment_status ON equipment(status);' +
  'CREATE INDEX IF NOT EXISTS idx_loans_active ON loans(equipment_id, returned_at);'
);

const now = () => new Date().toISOString();
const arr = x => Array.isArray(x) ? x : x ? [x] : [];
const tagsOf = x => [...new Set(arr(x).map(v => String(v).trim().toLowerCase()).filter(Boolean))];

function setTags(equipmentId, tags) {
  const add = db.prepare('INSERT OR IGNORE INTO tags(name) VALUES (?)');
  const get = db.prepare('SELECT id FROM tags WHERE name = ?');
  const link = db.prepare('INSERT OR IGNORE INTO equipment_tags(equipment_id, tag_id) VALUES (?, ?)');
  db.prepare('DELETE FROM equipment_tags WHERE equipment_id = ?').run(equipmentId);
  for (const name of tagsOf(tags)) {
    add.run(name);
    link.run(equipmentId, get.get(name).id);
  }
}

function hydrate(row) {
  if (!row) return null;
  row.tags = db.prepare(
    'SELECT t.name FROM tags t JOIN equipment_tags et ON et.tag_id=t.id ' +
    'WHERE et.equipment_id=? ORDER BY t.name'
  ).all(row.id).map(x => x.name);
  return row;
}

function getEquipment(id) {
  return hydrate(db.prepare('SELECT * FROM equipment WHERE id=?').get(id));
}

function addEquipment(x = {}) {
  if (!x.name) throw new Error('name is required');
  const result = db.prepare(
    'INSERT INTO equipment(asset_code,name,description,serial_number,status,location) ' +
    'VALUES(@assetCode,@name,@description,@serialNumber,@status,@location)'
  ).run({
    assetCode: x.assetCode || 'ASSET-' + Date.now(),
    name: x.name,
    description: x.description || '',
    serialNumber: x.serialNumber || null,
    status: x.status || 'available',
    location: x.location || ''
  });
  setTags(result.lastInsertRowid, x.tags);
  return getEquipment(result.lastInsertRowid);
}

function updateEquipment(id, x = {}) {
  const fields = [], params = { id, updatedAt: now() };
  const map = { assetCode:'asset_code', name:'name', description:'description',
    serialNumber:'serial_number', status:'status', location:'location' };
  for (const key of Object.keys(map)) if (x[key] !== undefined) {
    fields.push(map[key] + '=@' + key); params[key] = x[key];
  }
  const tx = db.transaction(() => {
    if (fields.length) {
      fields.push('updated_at=@updatedAt');
      db.prepare('UPDATE equipment SET ' + fields.join(',') + ' WHERE id=@id').run(params);
    }
    if (x.tags !== undefined) setTags(id, x.tags);
  });
  tx();
  return getEquipment(id);
}

function addLendee(x = {}) {
  if (!x.name || !x.email) throw new Error('name and email are required');
  const r = db.prepare(
    'INSERT INTO lendees(name,email,phone,notes) VALUES(@name,@email,@phone,@notes)'
  ).run({ name:x.name, email:x.email, phone:x.phone || '', notes:x.notes || '' });
  return db.prepare('SELECT * FROM lendees WHERE id=?').get(r.lastInsertRowid);
}

function checkout(x) {
  const tx = db.transaction(() => {
    const e = getEquipment(x.equipmentId);
    if (!e) throw new Error('equipment not found');
    if (e.status !== 'available') throw new Error('equipment is not available: ' + e.status);
    if (!db.prepare('SELECT id FROM lendees WHERE id=?').get(x.lendeeId)) throw new Error('lendee not found');
    const r = db.prepare(
      'INSERT INTO loans(equipment_id,lendee_id,picked_up_at,due_at,pickup_notes,condition_out) ' +
      'VALUES(@equipmentId,@lendeeId,@pickedUpAt,@dueAt,@pickupNotes,@conditionOut)'
    ).run({
      equipmentId:x.equipmentId, lendeeId:x.lendeeId, pickedUpAt:x.pickedUpAt || now(),
      dueAt:x.dueAt || null, pickupNotes:x.pickupNotes || '', conditionOut:x.conditionOut || ''
    });
    db.prepare('UPDATE equipment SET status="checked_out",updated_at=? WHERE id=?').run(now(), x.equipmentId);
    return loan(r.lastInsertRowid);
  });
  return tx();
}

function returnItem(x) {
  const tx = db.transaction(() => {
    const active = x.loanId
      ? db.prepare('SELECT * FROM loans WHERE id=? AND returned_at IS NULL').get(x.loanId)
      : db.prepare('SELECT * FROM loans WHERE equipment_id=? AND returned_at IS NULL ORDER BY picked_up_at DESC LIMIT 1').get(x.equipmentId);
    if (!active) throw new Error('active loan not found');
    db.prepare(
      'UPDATE loans SET returned_at=@returnedAt,return_notes=@returnNotes,condition_in=@conditionIn WHERE id=@id'
    ).run({ id:active.id, returnedAt:x.returnedAt || now(), returnNotes:x.returnNotes || '', conditionIn:x.conditionIn || '' });
    db.prepare('UPDATE equipment SET status=?,updated_at=? WHERE id=?').run(x.status || 'available', now(), active.equipment_id);
    return loan(active.id);
  });
  return tx();
}

function loan(id) {
  return db.prepare(
    'SELECT l.*,e.asset_code,e.name AS equipment_name,p.name AS lendee_name,p.email AS lendee_email ' +
    'FROM loans l JOIN equipment e ON e.id=l.equipment_id JOIN lendees p ON p.id=l.lendee_id WHERE l.id=?'
  ).get(id) || null;
}

function find(f = {}) {
  const where = [], params = {}, ts = tagsOf(f.tags);
  if (f.status) { where.push('e.status=@status'); params.status=f.status; }
  if (f.location) { where.push('e.location=@location'); params.location=f.location; }
  if (f.q) {
    where.push('(e.name LIKE @q OR e.asset_code LIKE @q OR e.serial_number LIKE @q OR e.description LIKE @q)');
    params.q='%' + f.q + '%';
  }
  if (f.available === true) where.push('e.status="available"');
  if (f.available === false) where.push('e.status<>"available"');
  const tagChecks = ts.map((tag, i) => {
    params['tag' + i] = tag;
    return 'EXISTS (SELECT 1 FROM equipment_tags et JOIN tags t ON t.id=et.tag_id ' +
      'WHERE et.equipment_id=e.id AND t.name=@tag' + i + ')';
  });
  if (tagChecks.length) where.push('(' + tagChecks.join(f.anyTag ? ' OR ' : ' AND ') + ')');
  params.limit = Math.min(Math.max(Number(f.limit) || 100, 1), 1000);
  params.offset = Math.max(Number(f.offset) || 0, 0);
  return db.prepare(
    'SELECT e.* FROM equipment e ' + (where.length ? 'WHERE ' + where.join(' AND ') : '') +
    ' ORDER BY e.name COLLATE NOCASE LIMIT @limit OFFSET @offset'
  ).all(params).map(hydrate);
}

function history(equipmentId) {
  return db.prepare(
    'SELECT l.*,p.name AS lendee_name,p.email AS lendee_email FROM loans l ' +
    'JOIN lendees p ON p.id=l.lendee_id WHERE l.equipment_id=? ORDER BY l.picked_up_at DESC'
  ).all(equipmentId);
}

function stats() {
  return db.prepare('SELECT status,COUNT(*) AS count FROM equipment GROUP BY status ORDER BY status').all();
}

function close() { db.close(); }

module.exports = { dbPath, addEquipment, updateEquipment, addLendee, getEquipment,
  checkout, returnItem, loan, find, history, stats, close };

